import { createHmac, timingSafeEqual } from 'node:crypto';
import type { PartnerWebhookPayload } from '@visaai/types';
import { VisaAiSignatureError } from './errors';

/**
 * Webhook verification.
 *
 * This mirrors the server's `partner-webhook-signature.ts` exactly. It is
 * duplicated rather than shared because a partner installs the SDK and nothing
 * else — and because the API and the SDK version independently. The
 * `webhooks.spec.ts` fixtures are generated by the server implementation, so a
 * divergence fails a test rather than a partner's integration.
 */

export const DEFAULT_TOLERANCE_SECONDS = 300;

export interface VerifyOptions {
  /** Current time in seconds. Injectable for testing. */
  nowSeconds?: number;
  /** Clock-skew tolerance. Default 300s. */
  toleranceSeconds?: number;
}

/**
 * Verify and parse a webhook.
 *
 * Pass the RAW request body, not a parsed-and-re-stringified object: JSON
 * round-tripping can reorder keys or change number formatting, and the
 * signature covers the exact bytes we sent.
 *
 * @throws VisaAiSignatureError when verification fails.
 */
export function verifyWebhook(
  rawBody: string,
  signatureHeader: string,
  secret: string,
  options: VerifyOptions = {},
): PartnerWebhookPayload {
  const now = options.nowSeconds ?? Math.floor(Date.now() / 1000);
  const tolerance = options.toleranceSeconds ?? DEFAULT_TOLERANCE_SECONDS;

  const parsed = parseSignatureHeader(signatureHeader);
  if (!parsed) throw new VisaAiSignatureError('malformed V-Signature header');

  if (Math.abs(now - parsed.timestamp) > tolerance) {
    throw new VisaAiSignatureError('timestamp outside the tolerance window');
  }

  const expected = createHmac('sha256', secret)
    .update(`${parsed.timestamp}.${rawBody}`)
    .digest('hex');

  const matched = parsed.signatures.some((candidate) =>
    constantTimeEquals(expected, candidate),
  );
  if (!matched) throw new VisaAiSignatureError('no matching signature');

  return JSON.parse(rawBody) as PartnerWebhookPayload;
}

/** Non-throwing variant for handlers that prefer a boolean. */
export function isValidWebhook(
  rawBody: string,
  signatureHeader: string,
  secret: string,
  options: VerifyOptions = {},
): boolean {
  try {
    verifyWebhook(rawBody, signatureHeader, secret, options);
    return true;
  } catch {
    return false;
  }
}

interface ParsedHeader {
  timestamp: number;
  signatures: string[];
}

function parseSignatureHeader(header: string): ParsedHeader | null {
  let timestamp: number | null = null;
  const signatures: string[] = [];
  for (const chunk of header.split(',')) {
    const [rawKey, rawValue] = chunk.split('=');
    if (rawValue === undefined) return null;
    const key = rawKey.trim();
    const value = rawValue.trim();
    if (key === 't') {
      if (!/^\d+$/.test(value)) return null;
      timestamp = Number(value);
    } else if (key === 'v1') {
      if (!/^[0-9a-f]+$/i.test(value)) return null;
      signatures.push(value.toLowerCase());
    }
  }
  if (timestamp === null || signatures.length === 0) return null;
  return { timestamp, signatures };
}

function constantTimeEquals(a: string, b: string): boolean {
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) return false;
  return timingSafeEqual(bufA, bufB);
}
